      const delta = variation * Math.min(7, baseRadius * 0.42);
      const radius = Math.max(baseRadius * 0.35, baseRadius + delta);
      const angle = Math.atan2(point.y, point.x);

      return {
        x: Math.cos(angle) * radius,
        y: Math.sin(angle) * radius,
      };
