class LivingMotifEngine {
  constructor(clock) {
    this.instanceId = globalThis.crypto?.randomUUID?.() ??
      `motif-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
    this.clock = clock;
    this.machine = new MotifStateMachine(clock.seed);
    this.listeners = new Set();
    this.motionQuery = typeof window.matchMedia === "function"
      ? window.matchMedia("(prefers-reduced-motion: reduce)")
      : null;
    this.reducedMotion = this.motionQuery?.matches ?? false;
    this.state = this.reducedMotion ? staticState() : this.machine.sample(clock.now());
    this.frame = this.frame.bind(this);
    this.onMotionChange = this.onMotionChange.bind(this);
    this.frameRequest = null;
    if (this.motionQuery?.addEventListener) {
      this.motionQuery.addEventListener("change", this.onMotionChange);
    } else {
      this.motionQuery?.addListener?.(this.onMotionChange);
    }
  }

  subscribe(listener) {
    if (typeof listener !== "function") {
      throw new TypeError("A Living Motif subscriber must be a function.");
    }

    this.listeners.add(listener);
    this.start();
    listener(this.state);

    return () => {
      this.listeners.delete(listener);
      if (!this.listeners.size) this.stop();
    };
  }

  snapshot() {
    return this.state;
  }

  start() {
    if (this.reducedMotion || this.frameRequest !== null || !this.listeners.size) return;
    this.frameRequest = window.requestAnimationFrame(this.frame);
  }

  stop() {
    if (this.frameRequest === null) return;
    window.cancelAnimationFrame(this.frameRequest);
    this.frameRequest = null;
  }

  onMotionChange(event) {
    if (event.matches === this.reducedMotion) return;
    this.reducedMotion = event.matches;

    if (this.reducedMotion) {
      this.stop();
      this.state = staticState(this.state);
      this.listeners.forEach((listener) => listener(this.state));
      return;
    }

    this.state = this.machine.sample(this.clock.now());
    this.listeners.forEach((listener) => listener(this.state));
    this.start();
  }

  frame() {
    this.frameRequest = null;
    this.state = this.machine.sample(this.clock.now());
    this.start();
    this.listeners.forEach((listener) => listener(this.state));
  }
}

// The only production instance. Every renderer subscribes to this object.
const motifEngine = new LivingMotifEngine(motifClock);

/* ==== canonical: shell/motif/renderers/renderer-core.js ==== */

function createMotifRenderer({
  host,
  oledElement,
  wipeElement,
  figureElements,
  settleScale,
}) {
  if (!host || !oledElement || !wipeElement || figureElements.length !== 4) {
    throw new Error("A motif renderer requires one OLED, one wipe and four figures.");
  }

  return Object.freeze({
    render(state) {
      host.dataset.motifCycle = String(state.cycle);
      host.dataset.motifPhase = state.phase;
      host.dataset.motifSeries = state.series.join(",");
      host.dataset.motifOledShape = state.oledShape;
      host.dataset.motifTimestamp = String(Math.round(state.timestamp));

      oledElement.setAttribute("d", path(state.oled, state.oledSmooth));

      const wipeWidth = 32 * state.eclipseProgress;
      const wipeX = state.phase === "eclipse-out" ? -16 : 16 - wipeWidth;
      wipeElement.setAttribute("x", String(wipeX));
      wipeElement.setAttribute("width", String(wipeWidth));

      figureElements.forEach((element, index) => {
        const figure = state.figures[index];
        const resolvedSettleScale =
          typeof settleScale === "function" ? settleScale() : settleScale;

        if (element.dataset.shape !== figure.shape) {
          element.innerHTML = MOTIF_GLYPHS[figure.shape];
          element.dataset.shape = figure.shape;
        }

        element.style.opacity = String(figure.opacity);
        element.style.transform = `translateY(${(
          figure.settle * resolvedSettleScale
        ).toFixed(2)}px)`;
      });
    },
  });
}

const HEADER_SETTLE_SCALE = motifConfig.figures.headerSettleScale;

